static const uint8_t GY[32] = {0x4f,0xe3,0x42,0xe2,0xfe,0x1a,0x7f,0x9b,0x8e,0xe7,0xeb,0x4a,0x7c,0x0f,0x9e,0x16,0x2b,0xce,0x33,0x57,0x6b,0x31,0x5e,0xce,0xcb,0xb6,0x40,0x68,0x37,0xbf,0x51,0xf5};

static void test_dbl(void) {
    TEST_SUITE("p256_point_dbl");
    for (int i = 0; i < NDBL; i++) {
        uint8_t in[96], out[96];
        jac_frombytes(in, &DBL_IN[i]);
        p256_point_dbl(out, in);
        ASSERT_EQ("dbl(P) matches reference", 1, jac_tobytes_eq(out, &DBL_OUT[i]));
    }

    // in-place: out aliasing in must give the same result.
    uint8_t buf[96];
    jac_frombytes(buf, &DBL_IN[0]);
    p256_point_dbl(buf, buf);
    ASSERT_EQ("dbl(P) in place matches reference", 1, jac_tobytes_eq(buf, &DBL_OUT[0]));
}

static void test_add(void) {
    TEST_SUITE("p256_point_add");
    for (int i = 0; i < NADD; i++) {
        uint8_t p1[96], p2[96], out[96];
        jac_frombytes(p1, &ADD_P1[i]);
        jac_frombytes(p2, &ADD_P2[i]);
        p256_point_add(out, p1, p2);
        ASSERT_EQ("P1+P2 matches reference", 1, jac_tobytes_eq(out, &ADD_OUT[i]));
    }

    uint8_t p1[96], p2[96];
    jac_frombytes(p1, &ADD_P1[0]);
    jac_frombytes(p2, &ADD_P2[0]);
    p256_point_add(p1, p1, p2);
    ASSERT_EQ("P1+P2 out aliasing P1 matches reference", 1, jac_tobytes_eq(p1, &ADD_OUT[0]));
}

static void test_mul_g(void) {
    TEST_SUITE("p256_point_mul — k*G against cryptography-derived pubkeys");
    uint64_t gx[4], gy[4];
    p256_fe_frombytes(gx, GX);
    p256_fe_frombytes(gy, GY);
    for (int i = 0; i < NMULG; i++) {
        uint64_t k[4], ox[4], oy[4];
        uint8_t oxb[32], oyb[32];
        p256_fe_frombytes(k, MULG_K[i]);
        p256_point_mul(ox, oy, k, gx, gy);
        p256_fe_tobytes(oxb, ox);
        p256_fe_tobytes(oyb, oy);
        ASSERT_EQ("(k*G).x", 0, memcmp(oxb, MULG_X[i], 32));
        ASSERT_EQ("(k*G).y", 0, memcmp(oyb, MULG_Y[i], 32));
    }
}

static void test_mul_q(void) {
    TEST_SUITE("p256_point_mul — k*Q for an arbitrary (non-G) point Q");
    uint64_t qx[4], qy[4];
    p256_fe_frombytes(qx, MULQ_BASE_X);
    p256_fe_frombytes(qy, MULQ_BASE_Y);
    for (int i = 0; i < NMULQ; i++) {
        uint64_t k[4], ox[4], oy[4];
        uint8_t oxb[32], oyb[32];
        p256_fe_frombytes(k, MULQ_K[i]);
        p256_point_mul(ox, oy, k, qx, qy);
        p256_fe_tobytes(oxb, ox);
        p256_fe_tobytes(oyb, oy);
        ASSERT_EQ("(k*Q).x", 0, memcmp(oxb, MULQ_X[i], 32));
        ASSERT_EQ("(k*Q).y", 0, memcmp(oyb, MULQ_Y[i], 32));
    }
}

int main(void) {
    test_dbl();
    test_add();
    test_mul_g();
    test_mul_q();
    test_summary();
    return 0;
}

